    interpretation: "慈禧的专权，是清代皇权制度与后宫临朝传统结合的产物。清制本严防后妃干政，辛酉政变却以垂帘听政的形式，将母育天子的伦理与皇权合法性对接，使太后临朝获得制度外衣。她能在近半个世纪内三度垂帘而不倒，关键在于牢牢抓住军机处与内廷，善用满汉平衡：既扶植曾国藩、李鸿章等汉族督抚以平乱自强，又在其功高之时加以裁抑；既支持洋务引进器物，又绝不容许触动皇权根本。戊戌政变扼杀了制度层面的改革可能，庚子西狩则暴露了她对外部世界的严重误判。清末新政虽由她亲手启动，却因失去时间与信任，未能挽救王朝。她是旧体制最熟练的守卫者，最终也成为它的陪葬人。",
