    summary: "咸丰六年（1856）至十年（1860），英国以亚罗号事件、法国以马神甫事件为借口，联合对中国开战。英法联军先后攻陷广州、大沽、天津，咸丰十年（1860）攻入北京，焚毁圆明园，清廷被迫签订《天津条约》与《北京条约》。中国增开十数处商埠、割让九龙司地方一区、允准外国公使驻京、鸦片贸易合法化，沙俄亦借机迫使清廷确认《瑷珲条约》并签订中俄《北京条约》，掠走大片领土。此战使中国主权进一步丧失，半殖民地化程度加深，亦直接刺激了洋务运动的兴起。",
    background: "道光二十二年（1842）《南京条约》签订后，英国并不满足既得权益。咸丰四年（1854），英国公使包令联合美、法两国向两广总督叶名琛提出修约要求，包括开放中国内地、公使驻京、鸦片贸易合法化等，遭清廷拒绝。英国商人及政府逐渐倾向以武力解决。咸丰六年正月（1856年2月），法国传教士马赖在广西西林县被知县张鸣凤处死，法国以此为口实；同年九月初十（1856年10月8日），中国商船亚罗号在香港注册的英国旗帜被广东水师扯下，英国驻广州领事巴夏礼借题发挥。两广总督叶名琛态度强硬又不作战备，英国公使包令与香港总督额尔金先后主张开战。英法两国一以护教、一以护旗为名，实为扩大在华通商与政治特权，战端由此而起。清廷方困于太平天国战事，无力南北兼顾，给了联军可乘之机。",
    chapters: [
      {
        heading: "战端再启陷广州",
        paragraphs: [
          "咸丰六年九月底（1856年10月下旬），英国驻香港海军以亚罗号事件为由，悍然炮击广州城墙，第二次鸦片战争爆发。两广总督叶名琛既不交涉也不设防，迷信扶乩，以为英人虚张声势。九月初十事件之后，英舰数艘轰击猎德、凤凰冈等炮台，守军伤亡甚重。叶名琛上奏朝廷，仅称「已驱逐夷船」，朝廷亦未察实情，防务就此搁置。",
          "咸丰七年十一月初（1857年12月底），英法联军五千六百余人集结珠江口，额尔金与法国全权大使葛罗联名照会叶名琛，限十日内入城修约。叶名琛复书拒绝。十二月十三日（1857年12月29日），联军轰塌广州城墙，守军巷战不敌，广州陷落。广东巡抚柏贵被俘后受挟制，仍在衙门理事，为联军维持秩序。",
          "叶名琛被俘后押往印度加尔各答，咸丰九年（1859）客死异乡。英法联军占据广州近四年，直到咸丰十一年（1861）才撤出。朝野对叶名琛评价两极，民间讥其「不战不和不守，不死不降不走」，实则折射出清廷上下于藩属体制与近代外交之间进退失据的窘境。"
        ]
      },
      {
        heading: "大沽先挫后失津",
        paragraphs: [
          "咸丰八年四月初八（1858年5月20日），英法联军舰船二十余艘进攻大沽口炮台，直隶总督谭廷襄督战不力，炮台一日之内尽失。联军沿河北上，兵临天津城下。清廷慌乱之中，派出大学士桂良、吏部尚书花沙纳为钦差大臣，赴天津议和。",
          "五月十六日、十七日（1858年6月26日、27日），清廷分别与英国、法国签订《天津条约》。主要条款为：公使驻京；增开牛庄、登州、台湾、淡水、潮州、琼州、汉口、九江、南京、镇江十处通商口岸；耶稣教、天主教教士得入内地传教；外国人得持照游历内地；赔偿英国银四百万两、法国银二百万两；鸦片以「洋药」名义纳税进口。俄国与美国亦趁火打劫，分别签订中俄、中美《天津条约》。",
          "咸丰帝对公使驻京一条引为奇耻，密令桂良在上海与英法交涉，愿以免税全换撤约，未果。咸丰九年五月（1859年6月），英法舰队到大沽口换约，英国海军司令贺布率舰闯入拦江沙河道，僧格林沁所部守军开炮还击，英舰三艘沉没，联军死伤四百余人，贺布亦负伤，换约被迫折回上海。这是开战以来清军唯一的一次胜仗，却为联军大举报复埋下祸根。"
        ]
      },
      {
        heading: "京师陷落焚名园",
        paragraphs: [
          "咸丰十年七月初（1860年8月初），英法联军一万八千人在北塘登陆，绕过大沽正面防务。七月二十一日（8月21日），大沽北岸主炮台石缝炮台失守，直隶提督乐善力战殉国。僧格林沁率马队退守通州。八月初七日（9月21日），联军进至八里桥，僧格林沁、胜保督率蒙古马队三万人冲锋，在联军洋枪洋炮下伤亡惨重，八里桥失守，通往北京的大门洞开。",
          "八月初八日（9月22日），咸丰帝以「北狩」为名，携后妃与肃顺、载垣等亲贵仓皇逃往热河避暑山庄，留恭亲王奕訢为钦差大臣，便宜行事。九月初五日（10月18日），英军全权代表额尔金为报复清廷虐待联军俘虏，下令焚毁圆明园。大火三日不灭，康雍乾百余年营建的万园之园化为焦土，园中所藏历代书画、典籍、珍玩被洗劫一空。",
          "九月十一日、十二日（10月24日、25日），奕訢分别与额尔金、葛罗签订中英、中法《北京条约》：确认《天津条约》完全有效；开天津为商埠；割九龙司地方一区给英国；赔偿英法军费各增至银八百万两；准许招工出洋。十一月十四日（11月14日），俄国以「调停有功」逼迫清廷签订中俄《北京条约》，确认《瑷珲条约》，并割去乌苏里江以东约四十万平方公里土地。咸丰十一年七月（1861年8月），咸丰帝病逝于热河，至死未回北京。"
        ]
      }
    ],
    interpretation: "第二次鸦片战争的实质，是西方列强以武力把中国强行纳入其主导的条约体系。修约之争是表，扩大市场、控制清廷是里。清廷的失败不在兵力悬殊一处，而在情报、外交、军制全面落后：叶名琛不知敌情，僧格林沁以骑兵冲击线膛枪炮，咸丰帝战和不定、一走了之。公使驻京打破了「天朝上国」的最后体面，清廷从此被直接置于列强外交监视之下。俄国不费一兵一卒而获大片领土，最为典型地暴露了清廷边备与外交的双重失灵。此战之后，奕訢、文祥等人上奏筹办洋务，总理各国事务衙门于咸丰十一年（1861）设立，洋务运动由此发端，中国开始了从「制夷」到「师夷长技」的艰难转折。圆明园之毁，则成为民族记忆中一道至今未平的伤疤。",
