    interpretation: "多尔衮一生，处于明清鼎革的转折点。他的历史作用可以分两面看：作为军事统帅，他抓住吴三桂乞兵、李自成立足未稳的空隙，一举入关定都，完成皇太极生前未能实现的目标，使一个人口不过百万的边疆政权入主中原，这份政治与军事上的决断力，在同时代无人能及。但作为执政者，他将圈地、投充、剃发等满洲旧制强制推行于汉地，激化满汉矛盾，使江南平定推迟数年，也替清廷积累了长久难以消解的民怨。他身后骤兴骤废，是八旗共主制残余与皇权集权冲突的缩影：摄政体制本是皇位危机下的妥协，一旦幼帝成年，功高震主者必然遭到清算。乾隆中期为其复爵平反，则说明入关一百余年之后，清廷已稳固到可以公允评价这位奠基者，而不必再畏惧其象征性威胁。",
