    interpretation: "福临处在清朝由关外政权转型为全国王朝的枢纽之上。他的皇位是多尔衮与豪格相争的折中产物，入关定鼎的实际操盘者是摄政王多尔衮。他所做的，是在多尔衮死后迅速收回皇权，并以满汉一体、尊孔崇儒、开科取士回答一个根本问题：以数十万满洲人如何统治上亿汉人？答案是武力征服之后，必须回到制度与文化的轨道上来。这一选择奠定清朝近三百年国祚的根基。但其统治始终在「一体」与「首崇满洲」之间摇摆，圈地、逃人、科场大狱暴露了征服王朝的内在紧张。二十四岁早逝，他将帝国交给八岁的玄烨与四大臣，平定南明残余、理顺满汉关系、确立皇权正统等未竟之业，由此成为康熙朝的核心任务。他既是开拓者，更是过渡者。",
