          "贵州「苗疆」为最后空白。都匀以东，古州（今榕江）、台拱（今台江）、清江、丹江、八寨、都江诸地，苗寨密布，向无流官，鄂尔泰称之为「新疆」。雍正七年（1729）起，鄂尔泰遣哈元生、张广泗等率兵进剿，次第开辟，设古州、台拱、清江、丹江、八寨、都江六厅，统称「新疆六厅」，以同知、通判领之。苗疆既入版图，贵州全省始无土府。"
