          "雍正十三年（1735）二月，古州、台拱一带苗民以包利、红银为首起事，聚众数万，围攻厅城，烽火遍于苗疆。时世宗已病笃，诏授哈元生为扬威将军、董芳为副将军，调七省兵会剿。乾隆元年（1736），张广泗总理苗疆事务，分兵深入，破诸苗寨，事乃平。苗疆平定后，于古州设镇，驻重兵，修屯政，苗民编户纳赋，新疆六厅之制始得巩固。"
