    interpretation: "改土归流之深层，是中央集权与边疆间接统治之间千年张力的总收束。自唐宋羁縻、元明土司，朝廷「以夷制夷」，求其名义臣服而已；土司世袭其地，自王其民，政令、兵权、财赋皆不归于上。雍正帝与鄂尔泰以雷霆手段，将世袭私权收归国家，使郡县体系直抵西南边徼，其规模与彻底程度远迈前代。就积极一面言，改流打破土司割据，减轻部民世役苛派，推动移民垦殖、文教普及与民族交融，奠定此后西南边疆治理的版图基础；就其代价言，改流每以兵威开路，乌蒙、古州、金川诸役死伤甚众，而流官体制仓促移植，亦激生新怨。乾嘉苗变，正是这场深刻转型的阵痛余波。",
