      {
        heading: "公行规条，行商沉浮",
        paragraphs: [
          "康熙五十九年（1720），行商公立行规，结为公行，统一货价，均摊税饷，约束散商，违者公议罚惩。公行之首由众行商推举，呈官府核准。乾隆二十四年（1759），英商洪任辉违禁赴宁波贸易，复赴天津投诉粤海关陋规，事闻于朝，两广总督李侍尧遂奏定《防范外夷五条规》：洋船到粤须行商承保，外商在粤须住行商商馆，借银有限度，雇役有禁律。自此行商约束外商之责更重，公行亦成为官府钦定之贸易机构。",
          "行商中巨富者，如同文行潘振承、怡和行伍秉鉴、天宝行卢观恒，皆积资数百万两。伍秉鉴于道光年间家财达二千六百万银元，时称天下首富之一。然商欠累积，行商积欠外商债务，官府责令破产清偿，抄家变产以偿。乾隆末年以后，行商因欠税欠债被革职抄家者接踵。道光初年，怡和行亦因垫赔欠款而渐形败落。行商百年基业，往往毁于一旦。",
          "行商之制，利在官府垄断税饷，弊在官吏中饱、行商困敝。海关监督与督抚层层勒索，规礼杂费名目繁多，每船进出口规礼不下数千两，皆由行商支应。行商不堪其扰，倒闭者接踵。康熙以来行商多时达数十家，至道光初年仅余十一家，且多积欠外商银两，勉强支撑。十三行之盛，至此已成强弩之末。"
        ]
      },
      {
        heading: "战火焚毁，制度终结",
        paragraphs: [
          "道光十九年（1839）正月，林则徐奉旨至粤禁烟，驻节越华书院，传集十三行行商，责令其规劝外商限期缴出鸦片，逾期则行商问罪。行商夹处于官府与外商之间，左右为难，伍秉鉴被革去顶戴，怡和行被罚巨款。道光二十一年（1841），英军兵临广州城下，行商被勒索赎城费六百万银元，家业荡然者甚众。十三行自此元气大伤。",
          "道光二十二年（1842）八月，中英签订《南京条约》，开放广州、厦门、福州、宁波、上海五口通商，废止行商制度，英商在五口得与华商自由交易。自此十三行独揽中西贸易之利尽失，广州贸易重心亦渐移于上海、香港。昔日巨商，或破产身死，或转为普通商贾，或流寓海外，百年积累之行商资本遂星散四方。",
          "咸丰六年（1856）十月，第二次鸦片战争期间，英军攻陷广州，十三行街市在炮火中焚毁，馆舍夷为平地。自康熙二十五年（1686）洋货行分立，至咸丰六年焚毁，凡一百七十年，十三行由盛而衰，终成陈迹。今广州文化公园一带，即十三行商馆旧址所在，犹存街巷旧名，供后人凭吊。"
        ]
      }
