    interpretation: "十三行是清廷在闭关体制下特许专营对外贸易的制度安排，其设立即在垄断税源、隔绝中外。行商承保代缴、代传达政令，兼具商务与外交之责，清廷借此「以官制商，以商制夷」，使对外贸易与中外交涉皆操之于行商。此制虽使广州成为十八世纪中西贸易之枢纽，关税与捐输成为朝廷及皇室重要财源，然亦使中外交往局限于广州一隅，士大夫对世界大势日益隔膜，通商之争终启兵端。一口通商之利，不敌坚船之利；十三行之焚毁，实为闭关体制崩溃之先声。",
