    background: "日本明治维新后走上扩张之路，制定了以征服朝鲜、满蒙乃至全中国为目标的「大陆政策」。光绪十年（1884），日本协助朝鲜开化党发动甲申政变，被袁世凯镇压，但日本借《天津会议专条》取得了与中国同等的出兵朝鲜之权。十九年（1893），日本将海军军费增至岁入三成，参谋本部反复推演对华作战。朝鲜为清朝藩属、东北屏障，战略地位攸关。二十年（1894）春，朝鲜爆发东学党起义，国王李熙向清廷乞援。李鸿章调直隶提督叶志超、太原镇总兵聂士成率军一千五百余人赴牙山。日本内阁决议出兵，陆续派兵八千余人进占汉城，据仁川、釜山等要害，蓄意点燃战火。清廷内部帝党主战、后党主和，李鸿章寄望列强调停，备战举棋不定。",
