          "开战之前，清军已在牙山、公州一带布防。六月二十七日（7月29日），日军四千余人进攻牙山以南的成欢驿，聂士成率部抵抗后败退。叶志超弃公州不守，率残部北逃平壤，沿途谎报大捷。清廷调集卫汝贵、马玉昆、左宝贵、丰升阿四军万余人入朝，与叶志超部合守平壤，由叶志超统一指挥。此时日军以第五师团为主力，分四路向平壤合围，战火迅速从海上燃至陆上。"
