    interpretation: "康有为一生，以变法始、以保皇终，其间的转折折射出近代中国新旧交替的时代困境。他以今文经学为变法张本，将孔子塑造为「托古改制」的先驱，既减少了变法阻力，也开启了思想解放的闸门；但其论说牵强附会之处，亦为守旧者所攻。戊戌变法失败的原因，守旧势力强大、维新派无兵无权、操之过急等皆是。流亡之后，康有为坚持君主立宪，与革命潮流渐行渐远，终为时代所弃。然其首倡维新、开启民智，使「变法」成为一代中国人的共识，此功不可磨灭。",
