          "《康熙字典》亦东传日本、朝鲜、越南。日本江户时代即有翻刻本，称「汉英字典」之祖本，明治间更有多种训点本；朝鲜王朝以之为科举写字之准。其流播之广，使二百一十四部首之法通行于整个汉字文化圈，至今汉字检索仍存其遗制。"
