    interpretation: "《康熙字典》之修，表面上是一部字书的编纂，实则是清廷文化战略的一环。满洲以少数入主中原，其统治之稳固，不仅在兵甲，更在能否接续汉字文化的正统。康熙帝以天子之尊，敕修字书，将文字的形、音、义纳入钦定规范，使天下士子在执笔之际，即与朝廷之准则相俯仰。此与修《朱子全书》以一理学、开博学鸿词科以揽士心，同出一辙。其深远影响有二：一则二百一十四部首之法由此定型，汉字检索体系沿用至今；一则科举既废，而《字典》已化为千家万户之案头工具，流布日本、朝鲜，成为汉字文化圈共同的遗产。王引之《字典考证》虽纠其失，适见其书不可废也。",
