    interpretation: "李鸿章的一生，是晚清衰亡史的缩影。他确有眼光：举国懵懂之时，已看到机器、枪炮、轮船、电报的力量，以一己之力把中国硬拽入近代化的门槛。但他也有难以逾越的局限：只学器物，不改制度；海军经费被挪修园苑，官督商办企业沦为衙门，淮军将领贪渎，「自强」终成空谈。外交上他奉行「以夷制夷」，却无国力为后盾，只得妥协退让换取苟安；《马关》《辛丑》之辱，非李一人之过，实为弱国之必然。梁启超「敬其才、惜其识、悲其遇」之评，至今仍为公论。",
