          "1925年，梁启超受聘清华学校国学研究院导师，与王国维、陈寅恪、赵元任并称四大导师，讲授《中国历史研究法》《儒家哲学》于清华、南开、东南诸校。1926年入北京协和医院割治肾病，手术误割好肾，元气大伤。1929年1月19日卒于北京协和医院，年五十六岁。临终前数日，犹口授《辛稼轩先生年谱》，至辛弃疾六十一岁止，未竟而卒。其著述辑为《饮冰室合集》，计一千四百余万字，遍及政治、经济、史学、文学、哲学诸域，为近代中国著述最富之人。"
