        paragraphs: [
          "《聊斋志异》的写法，是以唐传奇的婉曲细腻来写六朝志怪的题材。六朝志怪粗陈梗概，唐传奇始有意为小说，蒲松龄则兼取其长：情节委曲，细节丰盈，对话声口毕肖。写婴宁之笑，或浓笑、或纵笑、或掩口而笑，千姿百态；写鬼狐之境，幽明相通，幻中有真。史传笔法、传奇格局、志怪题材，三者熔为一炉，遂开生面。",
          "书成之后，先以抄本流传，雍正、乾隆间已有多种抄本在士林传阅。王士禛（渔洋山人）曾加评点，题诗「姑妄言之姑听之，豆棚瓜架雨如丝」，为之扬名。但全书正式刊刻，已在蒲松龄身后：乾隆三十一年（1766），浙江严州知府赵起杲据抄本刊成青柯亭本，虽删去部分篇目，聊斋自此广为流布，此后翻刻、评注、续书、仿作层出不穷。",
          "纪昀晚年撰《阅微草堂笔记》，有意与之分道扬镳，主张「尚质黜华」，不设幻言情，以学问入小说，代表了另一种志怪路数。但论想象之奇、文采之丽、人情之深，《聊斋志异》终为文言小说不可逾越的高峰。它上承魏晋志怪、唐人传奇之绪，下开《子不语》《夜雨秋灯录》一脉，戏曲、曲艺、绘画、影视改编至今不衰。"
        ]
