    interpretation: "《聊斋志异》的深层逻辑，是一个科场失意者的精神自救。蒲松龄把半生沦落的愤懑、对人世公道的渴望，尽数投注于狐鬼世界：人间缺的，狐鬼补上——科场无衡才之尺，便让盲僧以鼻辨文；吏治贪酷，便让席方平魂诉冥府；礼教束缚性情，便让婴宁笑傲人间。它以幻写真，非为志怪而志怪。在文学史上，宋元以后白话小说已成主流，文言系统式微已久，蒲松龄以一人之力承唐传奇余绪而集其大成，把文言小说推上最后也是最高的峰巅。身后纪昀虽另立一派，也未能掩其光焰；后世摹拟者虽多，终无人能继其神理。",
