          "在戍所，林则徐身处江湖之远，不避劳怨。他协助伊犁将军布彦泰兴办屯田水利，带头捐修阿齐乌苏大渠龙口工程；又奉命赴南疆库车、阿克苏、乌什、喀什噶尔、叶尔羌、和阗等地勘察垦务，三万里周历天山南北，所至清查地亩、勘办水渠，并于吐鲁番一带推广坎儿井，当地民众称为「林公井」。启程西行时他曾口占示家人：「苟利国家生死以，岂因祸福避趋之」，这两句诗正是他万里投荒而志节不衰的写照。"
