          "道光三十年（1850）正月道光帝驾崩，咸丰帝继位。其时广西会党蜂起，拜上帝会蓄势待发，局势危迫。咸丰帝甫即位，即于九月授林则徐为钦差大臣，驰赴广西督师。林则徐抱病就道，十月十九日（1850年11月22日）行至广东潮州，病卒于普宁县行馆，享年六十六岁。朝廷追赠太子太傅，谥文忠，咸丰元年归葬福州北郊金狮山。",
          "林则徐宦游半生，所至治河工、兴水利、平冤狱、肃烟毒，以经世致用之学见称于时；其在广州开译馆、察夷情、师西技之举，后经魏源据《四洲志》撰成《海国图志》，发为「师夷长技以制夷」之议，实为后来洋务自强思潮的先声。"
