    interpretation: "林则徐的遭际，是传统帝国撞入近代国际秩序时的一个缩影。他以经世之学办事，却在实践中最先察觉到中国已不在天下之中：组织译书、购置洋炮、考求夷情，皆是从「天朝上国」的迷梦里醒来的最初动作。鸦片战争不利，朝廷以钦差为替罪之人，问责一二臣工以求苟安，折射出道光一朝因循推诿的痼疾，也注定了此后的屈辱条约之路。而他在遣戍途中治河、在伊犁垦田，暮年仍抱病受命、死于王事，则把「苟利国家生死以」化为一生的践履。士大夫的担当与近代世界的逼迫，在他身上交汇成近代中国蹒跚起步的第一道转折。",
