        paragraphs: [
          "道光中年，鸦片流毒日深。英国为扭转对华贸易逆差，自道光初年大肆输运鸦片，至十八年（1838年）前后每年输入逾三万箱。白银滚滚外流，银贵钱贱，百姓完粮纳税负担倍增，国计民生两困。鸿胪寺卿黄爵滋上《严塞漏卮以培国本疏》，请重治吸食以断银漏；湖广总督林则徐力赞其议，奏言「若犹泄泄视之，是使数十年后，中原几无可以御敌之兵，且无可以充饷之银」。旻宁读之动容，遂决意严禁。道光十八年十一月，授林则徐为钦差大臣，驰赴广东查办海口事件。",
          "十九年（1839年）三月，林则徐抵广州，与两广总督邓廷桢合力，勒令外商缴烟具结。四月二十二日至五月十五日（1839年6月3日至25日），收缴鸦片二百三十七万六千二百余斤，于虎门海滩当众销毁，史称虎门销烟。二十年（1840年）六月，英国远征军封锁珠江口，鸦片战争爆发。英军北犯，陷定海，直抵大沽口，京师震动。旻宁游移于剿抚之间，先以「办理不善」革林则徐、邓廷桢之职，改派琦善赴粤议和；及琦善私允割让香港、赔款六百万银元之事败露，旻宁怒而下诏宣战。",
          "战端重开，清军处处被动。二十一年（1841年）二月，虎门炮台陷落，广东水师提督关天培力战殉国；七月，厦门失守；八月，第二次定海之战中，三总兵葛云飞、郑国鸿、王锡朋同时殉国，镇海、宁波相继陷落，两江总督裕谦殉节于镇海。二十二年（1842年）五月，吴淞之战，老将陈化成战死；六月，镇江陷落，副都统海龄自尽殉节。旻宁知战不可恃，遂决意求和。七月二十四日（1842年8月29日），钦差耆英、伊里布与英方全权代表璞鼎查在南京江面英舰「皋华丽」号上签订《南京条约》，割香港岛，赔款二千一百万银元，开广州、厦门、福州、宁波、上海五口通商。此为中国近代史上第一个不平等条约。"
        ]
