    interpretation: "平定准噶尔前后历时七十余年、跨越三朝，是清朝国家建构的关键一战。清朝之所以屡败屡战、矢志不渝，根源在于其大一统的政治逻辑：喀尔喀内附使清朝承担起保护漠北的义务，准噶尔一日强盛，京师与蒙古便一日不安；而准噶尔控制青藏、染指西域的扩张，更直接触及清朝的战略底线。康熙以亲征立威，乾隆以分化瓦解收功、以准部降将为先导，体现了清朝从武力征讨到政治瓦解的策略成熟。其结果不仅消除了北方草原最后一个能与清朝抗衡的游牧政权，更将天山南北纳入直接管辖，奠定今日中国西北版图之基础。伊犁将军的设立，标志清朝对西域的治理由羁縻转向驻军、屯田、建城并举的实边经略。",
