          "宣统三年八月十九日（1911年10月10日），武昌新军首义，汉阳、汉口继下，武昌据长江中流，震动天下。两月之间，南方十四省及北方数州县相继独立，清廷号令不出京畿。载沣被迫重新起用袁世凯，先授湖广总督，再任内阁总理大臣。袁世凯拥北洋重兵，一面以冯国璋部猛攻汉口、汉阳，压民军之和，一面遣使南下议和。十二月初，南北代表唐绍仪与伍廷芳在上海开议，议定清帝退位、建立共和、举袁世凯为临时大总统的框架。",
          "宗社党首领良弼誓主决战，扬言要重整兵马与民军决一死战。宣统三年十二月（1912年1月），革命党人彭家珍以炸弹刺杀良弼于北京，良弼伤重而亡，宗室胆寒，朝堂之上再无敢言战者。隆裕太后见大势已去，于十二月二十五日（1912年2月12日）代年仅六岁的溥仪颁布《退位诏书》：「特率皇帝将统治权公诸全国，定为共和立宪国体……总期人民安堵，海宇乂安，仍合满、蒙、汉、回、藏五族完全领土，为一大中华民国」，并授袁世凯以全权组织临时共和政府。自顺治元年（1644）清军入关，二百六十八年清祚告终；自秦始皇并天下，两千余年帝制亦随之而绝。",
