          "民国六年（1917）六月，安徽督军张勋以调停「府院之争」为名，率「辫子军」入京，于七月一日凌晨拥十二岁的溥仪重登宝座，复宣统年号，封官授爵，龙旗重悬。段祺瑞在马厂誓师讨逆，辫子军一触即溃。七月十二日，张勋逃入荷兰使馆，这场历时十二天的复辟闹剧草草收场。溥仪被迫第二次「退位」，但紫禁城内的小朝廷依旧运转如故。",
          "1924年十月，冯玉祥回师北京发动政变，修改优待条件，限令溥仪即日迁出紫禁城。溥仪避入日本公使馆，次年潜往天津，先后寓居张园、静园。在津七年，他与郑孝胥、罗振玉等遗老密图复辟，与日本军政要员频相往来。1931年九一八事变后，日本关东军以「帮助复清」为饵，派土肥原贤二将溥仪秘密接往东北。1932年三月，伪满洲国成立，溥仪就任「执政」，年号大同；1934年三月改称皇帝，年号康德，再行登极之礼。",
