          "在抚顺十年，溥仪从抗拒、恐惧转向交代罪行、认真改造，写下长篇自传《我的前半生》。1959年十二月四日，最高人民法院颁布特赦令，溥仪名列首批获释战犯，回到北京。此后他任全国政协文史资料研究委员会专员，以亲身经历撰写清末民初史料，1962年与护士李淑贤结为夫妻，过上普通市民的生活。",
          "1967年十月十七日，溥仪因肾癌病逝于北京，终年六十一岁。骨灰初葬八宝山革命公墓，1995年迁葬于清西陵崇陵东侧的华龙皇家陵园，与祖先为邻。自三岁登极到六十一岁病逝，溥仪的一生横跨清末、民国、新中国三个时代，历经皇帝、废帝、傀儡、战俘、公民五种身份，堪称中国从帝制走向共和的一部活档案。"
