    summary: "顺治元年（1644）三月，李自成攻破北京，崇祯帝自缢，明朝灭亡。镇守山海关的明将吴三桂拒绝降附，向清朝摄政王多尔衮借兵。四月二十二日，多尔衮率八旗军与吴三桂联军在山海关一片石大败李自成。五月初二日，清军进入北京；十月初一日，顺治帝在紫禁城即位，颁诏天下。清军入关结束了明朝二百七十六年的统治，开启清朝二百六十八年的中原统治，是中国历史上又一次大规模王朝更替，也为此后统一多民族国家版图的形成奠定基础。",
    background: "明朝自万历末年渐趋衰败，党争不断，府库空虚；崇祯一朝又遇连年旱蝗与瘟疫，陕西、河南赤地千里，流民百万。为筹辽东军饷，朝廷连年加派三饷，赋税尽数压于贫民，反将更多百姓推向起义队伍。崇祯十四年（1641）松锦之战，洪承畴所率十三万明军精锐在辽东全军覆没，关外仅余山海关一座孤城。明朝实是在两线作战的长期消耗中油尽灯枯。崇祯十七年（1644）正月，李自成在西安建国大顺，改元永昌，随即挥师东进；三月十九日北京陷落，崇祯自缢于煤山。此时山海关总兵吴三桂麾下有四万关宁铁骑，扼守明军关外最后一座要塞，成为大顺与清朝双方争夺的关键力量。关外满洲政权经皇太极三十年经营，已征服漠南蒙古与朝鲜，改国号曰清，对中原虎视眈眈。皇太极去世后，六岁的顺治帝即位，由叔父多尔衮摄政，清军正待入关。",
