          "崇祯之死并非骤然。自万历、天启以来，明朝深陷党争，宦官与东林互相倾轧，府库日虚；崇祯一朝又遇连年旱蝗与瘟疫，陕西、河南赤地千里，流民百万。为筹辽东军饷，朝廷连年加派三饷，赋税尽数压于贫民，反将更多百姓推向起义队伍。崇祯十四年（1641）松锦之战，洪承畴所率十三万明军精锐在辽东全军覆没，自此关外仅余山海关一座孤城。明朝是在两线作战的长期消耗中油尽灯枯，北京的陷落不过是压垮骆驼的最后一根稻草。"
