          "行至滦州，吴三桂听闻大顺权将军刘宗敏在北京酷刑追赃，拷打降官，父亲吴襄被严刑夹禁，爱妾陈圆圆亦被掠去。史家多以为「冲冠一怒为红颜」只是表层，逼反吴三桂的根本，是大顺政权对士绅阶层的全面打击。吴三桂当即回师，击溃唐通，重占山海关。他随即陷入绝境：西有大顺大军压境，东有满洲铁骑虎视。四月，吴三桂致书清朝摄政王多尔衮，以「借兵复仇」为名，请清军入关共击李自成。多尔衮接信，立即放弃原定从蓟镇入塞的计划，率八旗精锐昼夜兼程，直奔山海关。"
