          "四月二十二日（公历5月27日）上午，吴三桂率军开关出战，双方在一片石一带厮杀，血战至午。忽狂风骤起，飞沙走石，多尔衮乘势令两翼骑兵突然出击，直冲大顺军阵。大顺军久战疲惫，猝不及防，阵脚大乱，溃不成军，刘宗敏亦中箭负伤。李自成见大势已去，下令撤退。清军与吴三桂追击四十余里，大顺军沿途死伤无数。李自成退至永平，怒杀吴襄全家，二十九日在北京匆匆举行即位大典，次日便焚毁宫殿，率军西撤。山海关一战，就此决定此后近三个世纪中国的统治者。"
