    interpretation: "施琅一生，最具争议处在于其反复易主：先随郑芝龙降清，再投郑成功抗清，终因家仇而再度降清，在传统忠节观下备受指责。然观其平台之后不修私怨、亲祭郑成功之庙，又力谏留台、反对弃地，可见其志不止于报复。从大历史观之，澎湖一役结束了明郑与清廷隔海对峙的局面；康熙二十三年（1684）台湾设府分县，使中央王朝首次将台湾本岛纳入郡县体系，有效治理由此奠基。施琅以海上枭雄之身，经略海疆，其个人虽有可议之处，然于国家统一、海防筹画，实有不可磨灭之功。",
