    interpretation: "十全武功奠定了今日中国疆域之基础。平准定回，新疆二万余里入版，置伊犁将军直辖；廓尔喀战后，金瓶掣签与驻藏大臣之制确立，边疆治理由羁縻而趋直接。这是康雍乾三代对准噶尔七十年战争的收束，也是清朝武功的极点。代价同样惊人：十役军费，据《清史稿·食货志》所载，用银至一万万两以上，第二次金川一役即耗七千万两。八旗、绿营已露腐态，木果木之败可见一斑。乾隆晚年好大喜功，和珅专政，吏治渐坏。嘉庆元年（1796）白莲教起义起，清朝由盛转衰。「十全」之名，实为盛极而衰的转折点。",
