    summary: "《四库全书》是清乾隆帝敕修的中国古代最大丛书。乾隆三十八年（1773）开设四库全书馆，以纪昀为总纂官，聚戴震、邵晋涵等学者三百六十余人，历时十年，至乾隆四十七年（1782）首部文渊阁本抄成。全书按经、史、子、集四部分类，收书三千四百六十一种、七万九千三百余卷，分装三万六千余册，先后抄成七部，分藏文渊、文溯、文源、文津及文宗、文汇、文澜七阁。修书同时，清廷禁毁书籍三千一百余种，于中国古代文献既有保存，亦有摧残。",
    background: "清乾隆中叶，国家承平，府库充盈。乾隆帝以文治自诩，欲仿前代修书之盛，且志在超越《永乐大典》。乾隆三十七年（1772）正月，乾隆帝下诏征求天下遗书，初意不过扩充内府藏书。安徽学政朱筠奏请从《永乐大典》中辑录亡佚古籍，获采纳。次年正月，乾隆帝正式开设四库全书馆，以皇六子永瑢、大学士于敏中为正总裁，纪昀、陆锡熊为总纂官。其时清廷已平定准噶尔，武功极盛，乾隆帝欲再立文化伟业，使文治与武功并称。修书另有深意。乾隆帝深知，天下典籍之中，明代及明清之际著述多有不利于清廷者。借征书之名，可将民间藏书尽收朝廷掌握，进而查缴禁毁，统一学术思想。于是修书与禁书并行，一体两面：所收者归入四库，所忌者付之一炬。盛世修典之盛，同时亦是思想统制之严。",
    chapters: [
      {
        heading: "开馆修书，十年功成",
        paragraphs: [
          "乾隆三十七年（1772）正月，乾隆帝下诏征求天下遗书，各省纷纷进呈。次年正月，乾隆帝正式开设四库全书馆，以皇六子永瑢、大学士于敏中为正总裁，纪昀、陆锡熊、孙士毅为总纂官，下设纂修、校阅、催办、缮书等官，参与学者先后达三百六十余人。纂修各有分工：戴震主治经部，邵晋涵主治史部，周永年主治子部，皆一时之选。凡进呈及内府所藏之书，先由纂修官校阅，拟写提要一篇，述其作者、内容、版本，再由纪昀笔削统一，呈乾隆帝裁定去取。",
          "全书按经、史、子、集四部分类，故名「四库」。自乾隆三十八年（1773）开馆，至乾隆四十七年（1782）正月第一部文渊阁本抄成，前后历时十年。共收书三千四百六十一种、七万九千三百零九卷，分装三万六千余册、六千一百余函，另附《四库全书总目》二百卷、《四库全书简明目录》二十卷。其收书之富、卷帙之巨、门类之全，远超《永乐大典》，为中国古代丛书之冠。",
          "书成前后，纪昀总撰《四库全书总目提要》二百卷，著录图书三千四百六十一种，存目六千七百九十三种，合计一万零二百五十四种。每书先列书名、卷数、作者，次为提要，考版本之源流，论内容之得失，辨真伪精粗。《提要》不仅是一部目录，更是一部中国学术史，对历代典籍作系统整理，纪昀一人笔削定稿，其学术眼光与文字功力，为后世学者所推重。"
        ]
      },
      {
        heading: "七阁分藏，书命多舛",
        paragraphs: [
          "《四库全书》先后缮写七部，分藏七阁。北京紫禁城文渊阁、圆明园文源阁、承德避暑山庄文津阁、盛京（今沈阳）文溯阁，称「北四阁」，专为御览而设；镇江金山文宗阁、扬州大观堂文汇阁、杭州西湖孤山文澜阁，称「江南三阁」，准许士子入阁抄阅。文渊阁本成于乾隆四十七年（1782），文溯阁本成于四十八年，文源阁本成于四十九年，文津阁本成于五十年，江南三阁则至乾隆末年陆续完成。",
          "七部抄本命运多舛。咸丰十年（1860），英法联军攻入北京，焚毁圆明园，文源阁本随之化为灰烬。太平天国战争中，镇江文宗阁本、扬州文汇阁本毁于战火，片纸无存。杭州文澜阁本亦遭兵燹，散佚大半，经杭州藏书家丁申、丁丙兄弟冒死抢救，并先后三次补抄，方才大致恢复旧观，成为江南三阁仅存之硕果。",
          "七部之中，文渊阁本今藏台北故宫博物院，保存最为完整；文溯阁本迭经播迁，一度藏于沈阳，今藏甘肃省图书馆；文津阁本于一九一五年自承德运抵北京，今藏中国国家图书馆；文澜阁本今藏浙江图书馆，补抄部分仍可辨识。四部基本完整，已是万幸；文源、文宗、文汇三部则彻底亡佚，成为中华文化不可挽回之损失。"
        ]
      },
      {
        heading: "寓禁于征，典籍遭劫",
        paragraphs: [
          "乾隆帝修书，与禁书并行。自乾隆三十九年（1774）起，清廷借征书之名查缴禁书，凡有诋斥清朝、语涉夷狄、有碍清廷忌讳者，一律查毁。地方督抚层层加码，藏书之家为求自保，往往自行焚毁。据后世学者统计，禁毁书籍达三千一百余种，几与《四库全书》所收之数相当；销毁书板八万余块，被抽毁、删改者不计其数。修书与禁书，实为乾隆帝文治政策的一体两面。",
          "编纂期间，文字狱频发。徐述夔《一柱楼诗》案、王锡侯《字贯》案，皆因进呈书籍、检举告讦而起，牵连广泛。藏书家惴惴不安，进书者或反获罪，献书之风因此中衰。四库馆臣对所收之书亦加审查，凡遇「胡」「虏」「夷狄」等字样，辄予删改窜易，乃至整篇抽毁，使许多典籍失去本来面目。明清之际的野史、笔记，毁坏尤甚，其中多有记清初史事者。",
          "《四库全书》之编，既是对历代典籍的空前整理，也是皇权对文化的一次全面整编。保存文献之功与禁毁篡改之过，集于一身。乾隆帝以天子之尊，总揽天下典籍之存废去取，其规模与力度远超前代。自此之后，朝廷不仅是典籍的保存者，更成为学术的裁判者；士人著述立说，不得不先以朝廷标准为权衡，乾嘉学者转而埋头考据，与思想禁锢不无关系。"
        ]
      }
    ],
    interpretation: "《四库全书》是中国古代文献的一次空前整理，也是皇权对文化的一次全面整编。其功在保存：从《永乐大典》中辑出佚书三百八十五种，使许多宋元以前古籍重见天日；纪昀总定的《四库全书总目提要》二百卷，著录与存目合计一万零二百五十四种，集古代目录学之大成，至今仍是研治古籍的锁钥。其过在摧残：禁毁书籍三千一百余种，几与所收之数相当，明清之际反清文献毁灭尤甚；所收之书，凡涉「胡」「虏」「夷狄」字样，辄加删改，典籍失去本来面目。存废去取，不依文献价值，而以政治标准。它既是传统学术的总结，也是君主专制在文化领域登峰造极的标志。",
