          "1919年10月，孙中山改组中华革命党为中国国民党。1921年5月，他在广州就任非常大总统。1922年6月，陈炯明部叛变，炮轰观音山总统府，孙中山避登永丰舰，亲率海军平叛五十六日，蒋中正登舰侍卫，自此见重。1924年1月，中国国民党第一次全国代表大会在广州举行，确立联俄、联共、扶助农工三大政策，允共产党员以个人身份加入国民党；5月创办黄埔军校，以蒋中正为校长。是年11月，孙中山应冯玉祥之邀北上共商国是，主张召开国民会议、废除不平等条约，行至天津肝疾转剧。1925年3月12日，孙中山病逝于北京铁狮子胡同行馆，享年五十九岁，遗言「革命尚未成功，凡我同志仍须努力」。"
