    interpretation: "孙中山的历史地位，在于他以一介布衣终结了延续两千余年的君主专制，打开共和的闸门。其所以能成事，一在横跨中西的视野——他是系统接受西方医学与政法教育的新式知识分子，而非旧式士大夫；二在组织与策略的不断调适——从兴中会、同盟会到改组后的国民党，从联络会党转向运动新军、扶助农工；三在理论建构——三民主义不止于反清，更将政权更迭引向土地、民生与权力结构的根本变革。然其局限亦显：始终未能建立真正可靠的革命武装与基层政权，屡屡依托一派军阀打倒另一派军阀。辛亥之功，在推翻帝制、播扬共和观念；其未竟之业，则待后来者续成。",
