          "三月十九日，太平军轰塌南京城垣入城，杀陆建瀛，江宁将军祥厚战死于满城。洪秀全改南京为天京，定为都城，入居原两江总督衙署，改筑天王府。是年冬，颁布《天朝田亩制度》，计口授田，凡天下田天下人同耕；又立圣库，禁私财，男女分馆，开科取士。然战事方殷，其制多未施行。天京既定，分兵北伐、西征：林凤祥、李开芳、吉文元率军二万余北伐直隶，转战六省，逼近天津，终因孤军无援，于咸丰五年在山东连镇、冯官屯全军覆没；西征军再克安庆、九江、武汉，石达开经略江西，十余府州望风归附。"
