          "十一月，洪秀全诛韦昌辉，以石达开为义王、通军主将，然疑忌不改，以长兄洪仁发、次兄洪仁达牵制之。咸丰七年五月，石达开率精锐十余万出走天京，转战浙江、福建、江西、湖南、广西，咸丰十一年入川，同治二年（1863）在大渡河紫打地陷入绝境，部众七千余被诛，石达开就义于成都。经天京一事变，开国诸王或死或走，太平天国元气大伤，军事由战略进攻转入防御。"
