          "同治三年（1864）春，曾国荃部合围天京，掘地道轰城，屡为守军所破。四月，洪秀全病逝，长子洪天贵福嗣位为幼天王。六月十六日（公历7月19日），湘军轰塌龙脖子地道，城陷。李秀成护幼主突围，被俘于方山，写自述数万言后遭杀害；幼主走广德、江西，九月被俘，十一月就义于南昌。其时余部在闽南、广东继续抵抗，至同治五年（1866）正月，汪海洋战死于广东嘉应州，太平天国余烬始熄。"
