    interpretation: "太平天国以宗教聚众、以战立国，其兴也骤，其亡也忽。拜上帝会虽能动员底层，而政教合一的体制权力无制：诸王世袭、等级森严，圣库之制行于下，王府奢靡于上。天京事变的根源，正在神权与王权的不可调和。从大历史看，它加速了清王朝的崩解：八旗绿营无用，湘淮军起，兵权下移于督抚，满汉权力格局由此改变，洋务运动随之而起；战争亦造成江南人口巨大损失，苏南、皖南、浙江数十年方得恢复。它既是旧式农民战争的巅峰，也是近代社会矛盾总爆发的先声。",
