    interpretation: "摊丁入亩的实质，是国家放弃以人身控制为依据的丁税，转而完全以土地为征税之本。编审既废，国家与编户齐民的人身依附随之松弛，劳动力得自由流动，为工商业与城市经济注入活力。于财政而言，丁银入地后税基稳定、征收简便，州县代赔之弊大减，又与耗羡归公、养廉银相配合，构成世宗整肃财政的一环。其局限亦明：丁银既入地亩，地主每以加租转嫁，佃户未必真受其惠；人口激增而耕地有限，人均田亩日蹙，流民、会党之患伏于盛世之中。然就制度演进而言，它终结了相沿两千余年的人头税，完成自唐代两税法、明代一条鞭法以来赋役合一的漫长进程，实为中国传统赋役制度之收束，亦近代田赋制度之开端。",
