          "光绪二十二年（1896），谭嗣同以同知衔赴江苏候补，在南京居住约一年。公余之暇，闭门著书，写成《仁学》二卷，五十篇，约五万字。此书以「仁」为天地万物之本，以「通」为仁之实现，主张上下通、中外通、男女内外通，打破一切人为隔阂。",
          "书中最大胆之处，在于将三纲五常斥为「网罗」，倡言「冲决网罗」，直斥君主专制为「大盗」，指名教伦理为钳制人心之具。他吸收西方科学与民主之说，又融汇佛学大悲度世的精神，提出「以心挽劫」的救世主张，其激烈程度为同时代人所罕见，章太炎后来虽与之论学不合，也不能不承认其思想的锋利。",
          "《仁学》写成后并未立即刊行，先在维新同志间传阅。戊戌政变后，谭嗣同遇难，《仁学》由梁启超等在日本陆续刊布，遂广为流传。它既是维新运动的理论结晶，也是近代中国思想解放的先驱之作，其冲决网罗之论，下启五四时代打倒孔家店的思想潮流。"
