    interpretation: "清代文字狱非寻常刑狱，乃皇权专制达于极点之产物。三朝君主皆非庸暗之主，然虑及满汉之防、正统之辨，宁严毋宽，宁枉毋纵。其深意不止于惩一儆百，更在重塑士林精神：天下读书人只许颂圣，不许议政；只许读经，不许存明。康熙以宽柔济严猛，雍正以刻核示天威，乾隆则以禁毁典籍、统制思想集其大成。其后果有二：一则士林风气为之一变，经世致用之志消磨，乾嘉考据虽精，究为避祸之学；二则文化典籍横遭芟夷，历史记忆被强行切割，元气之伤，非一代可复。龚自珍后来咏「避席畏闻文字狱，著书都为稻粱谋」，正道出士人余悸。",
