    interpretation: "吴三桂一生四易其主：明臣、降李、降清、叛清，其抉择始终以保全自身实力为第一考量，折射出明末辽东军事集团在王朝鼎革中的生存逻辑。他引清军入关，直接改变了甲申年的天下格局，使清廷得以定鼎北京；他又绞杀永历帝，为清廷荡平南明，自己则成为开国功臣与贰臣叛将的双重角色。三藩之乱表面上是撤藩激变，实则是清初以满洲为核心的皇权与汉族军阀实力派之间的必然冲突。康熙帝以二十之龄平定叛乱，借此完成中央集权，消弭藩镇之弊，为康乾盛世奠定根基；而吴三桂兴兵八年，终因大义有亏、战略保守、后继无人而覆灭，成为后世反复评说的悲剧人物。",
