    summary: "光绪二十四年（1898）四月二十三日，光绪帝采纳康有为、梁启超等维新派主张，颁布《明定国是诏》，推行变法。一百零三日间，朝廷颁行新政诏令一百余道，涉及废八股、办学堂、裁冗署、练新军、兴农工商等事。变法触犯以慈禧太后为首的守旧势力利益，八月初六日慈禧发动政变，重新训政，光绪帝被囚于瀛台，谭嗣同、杨锐、林旭、刘光第、杨深秀、康广仁六人于菜市口就义，康梁流亡海外。除京师大学堂外，新政悉数废止。戊戌变法是中国近代一次自上而下的改革尝试，也是思想启蒙的重要转折。",
    background: "甲午一役，北洋水师全军覆没，光绪二十一年（1895）三月《马关条约》签订，割台湾、赔银二万万两，举国震动。同年四月，康有为联合在京会试的举人一千三百余人上书，请求拒和、迁都、变法，史称「公车上书」。此后维新思潮涌动，康有为接连上书光绪帝，于北京、上海组织强学会，梁启超主《时务报》、严复译《天演论》，风气渐开。光绪帝亲政后受制于慈禧，见国势日危，亟思图强，屡读康有为折稿，深为所动，遂于二十四年四月二十三日颁《明定国是诏》。其时列强瓜分之议甚嚣尘上，胶州湾、旅顺大连、广州湾相继被租借，亡国之忧迫在眉睫，此为变法之直接动因。",
    chapters: [
      {
        heading: "国是诏下，维新启幕",
        paragraphs: [
          "光绪二十四年四月二十三日（1898年6月11日），光绪帝颁《明定国是诏》，宣布变法。诏中明言「国是不定，则号令不行」，令中外臣工奋发有为。五日后，光绪帝在颐和园仁寿殿召见康有为，畅谈变法方针，命其在总理各国事务衙门章京上行走，准其专折奏事。康有为先后呈递《应诏统筹全局折》《日本变政考》等，为变法提供蓝本。五月十五日（7月3日），光绪又召见梁启超，赏六品衔，办理译书局事务。自此康梁得侍左右，新政次第展开。",
          "变法伊始，帝后两党已暗流涌动。四月二十七日，光绪下旨将帝师翁同龢开缺回籍，剪去皇帝羽翼；同日授大学士荣禄署理直隶总督，节制北洋三军，拱卫京畿。慈禧又谕令光绪，凡授任二品以上大臣须诣颐和园谢恩，实为钳制人事。光绪亲政以来，京中要职多为后党所据，变法只能在夹缝中推进，为后来的政变埋下伏笔。"
        ]
      },
      {
        heading: "百日新政，诏令纷驰",
        paragraphs: [
          "自四月二十三日至八月初六，新政推行一百零三日，朝廷颁诏谕一百余道，史称「百日维新」。其要端有四：教育上废八股取士，改试策论，改书院为学堂，创办京师大学堂，设译书局、奖励游学；经济上设农工商总局，兴办铁路、邮政，奖励农学工艺，准民间设厂开矿；军事上裁汰绿营，编练新军，设武备学堂；政治上广开言路，准士民上书言事，裁撤詹事府、通政使司等冗署冗员。",
          "新政锐意更张，却处处触动既得利益。废八股使天下士子顿失晋身之阶，数百京官集于礼部衙门请愿；裁冗署令数十衙门官员骤失生计，怨声载道。地方督抚中，仅湖南巡抚陈宝箴认真奉行，设时务学堂、南学会，延梁启超主讲；两江总督刘坤一、湖广总督张之洞等封疆大吏多观望敷衍，诏令到了地方往往搁置不行。百日之间上谕纷飞，而下之应者寥寥。",
          "为打破僵局，光绪帝行雷霆手段。七月十九日（9月4日），因礼部主事王照上书被堂官阻格，光绪怒将礼部尚书怀塔布、许应骙等六堂官革职，赏王照三品顶戴。七月二十日（9月5日），又赏杨锐、刘光第、林旭、谭嗣同四品卿衔，在军机章京上行走，参预新政事宜。此四人入值军机，新政章奏多出其手，权势顿显，后党侧目，新旧之争遂趋于白热化。"
        ]
      },
      {
        heading: "瀛台变起，六君喋血",
        paragraphs: [
          "后党早已磨刀霍霍。八月初三日，御史杨崇伊上密折，请太后训政。当夜，谭嗣同只身访袁世凯于法华寺，劝其杀荣禄、围颐和园，以兵勤王。袁世凯表面应承，离京后即向荣禄告密。关于袁世凯告密与政变的先后，学界素有争论：一说告密直接引发政变，一说政变在先、告密只是推波助澜；至于围困颐和园、软禁太后之说，源于毕永年《诡谋直纪》，真伪至今争论未决。然袁氏背信出卖维新派，史有明征。",
          "八月初六日（9月21日），慈禧由颐和园还宫，宣布重新训政，光绪帝被囚于瀛台涵元殿，失去自由。康有为已于前一日离京，经天津逃往香港；梁启超避入日本使馆，后剪发易服东渡。八月十三日（9月28日），未经任何审讯，杨深秀、杨锐、林旭、刘光第、谭嗣同、康广仁六人被押赴菜市口斩首，史称「戊戌六君子」。谭嗣同本可出走，却坚留京师，以死明志，其从容就义震动天下。",
          "政变之后，新政除京师大学堂外悉数废止，新党株连甚广，陈宝箴革职永不叙用，张荫桓遣戍新疆。光绪帝虽保帝位，形同囚徒，此后十年幽居瀛台，至死未能复位。变法持续百零三日即告夭折，然维新思潮未随六君之血俱灭，反而由潜流而澎湃，成为此后清末新政、立宪运动乃至革命思潮的先声。"
        ]
      }
    ],
    interpretation: "戊戌变法之败，根于维新派有君权而无兵权、有诏令而无治权。光绪一纸诏书可行于上，而督抚观望于下，满洲亲贵、科举士子、被裁官员层层抵触。维新诸子求治太急，百日之间诏令百余道，事事草创，处处树敌，将本可分化守旧阵营的温和措施与最易招致反弹的措施一齐推出，反促旧势力合流。政变之后，慈禧与守旧派全面回潮，排外情绪与庚子之变相继而来；然变法所开启的报刊、学会、新学与民权议论已不可遏，京师大学堂硕果仅存，清末新政、立宪运动乃至革命思潮，皆沿此一脉展开。",
