          "10月11日下午，武汉三镇光复。革命党人因孙中山、黄兴均不在汉，群龙无首，遂强推与革命素无渊源的第二十一混成协协统黎元洪为都督，借其旧望稳定人心。湖北军政府以黄帝纪元，悬十八星旗，通电号召各省响应。汉口、汉阳次第光复，武汉三镇遂成全国革命的中枢。"
