        text: "今全国人民心理多倾向共和，南中各省既倡议于前，北方诸将亦主张于后，人心所向，天命可知。予亦何忍因一姓之尊荣，拂兆民之好恶？是用外观大势，内审舆情，特率皇帝将统治权公诸全国，定为立宪共和国体。",
