    background: "顺治十八年（1661）正月，世祖福临崩，遗诏命第三子玄烨继位。玄烨生于顺治十一年（1654），曾出天花而幸存，因有免疫之身，成为继位的重要考量。即位之初由索尼、苏克萨哈、遏必隆、鳌拜四臣辅政。其时天下初定：南明永历政权虽已于上年亡于缅甸，但平西王吴三桂镇云南、平南王尚可喜镇广东、靖南王耿继茂与耿精忠父子镇福建，三藩坐大，岁耗朝廷赋税之半；东南海上郑氏据台湾，与清廷隔海对峙；东北沙俄乘隙侵入黑龙江流域，筑雅克萨城盘踞；西北漠西准噶尔部首领噶尔丹崛起，兼并四卫拉特，虎视喀尔喀蒙古。朝中辅臣鳌拜结党专权，矫诏诛杀大臣；民间满汉矛盾未消，汉族士大夫心存故国。一个武功未靖、满汉未融、权臣在朝的初定之局，便落在八岁天子肩上。",
