    interpretation: "玄烨之世，论者比之汉武、唐宗。其能成大业，约有三端：一则满汉并用，博学鸿词、祭孔崇儒，以文教收揽士心，化鼎革之仇为君臣之分；二则知人善任而不疑，平三藩倚图海、赵良栋，平台湾专任施琅，亲征调度而非浪战；三则恩威并施，尼布楚定约以遏俄衅，盟旗分治以安漠北，不独恃兵力。然其晚年宽仁过甚，吏治渐弛，亏空成风；夺嫡之争骨肉相残，十余年国本动摇，至雍正朝始厉行整饬。滋生人丁永不加赋，为人口繁息开路，亦为摊丁入亩张本。六十一年间，版图规模、制度框架、文化格局俱已立定，故《清史稿》论曰：虽曰守成，实同开创。",
