    interpretation: "雅克萨之战的胜利，不在战阵之烈，而在庙算之深。康熙帝先平三藩、收台湾，再专力东北，次序井然；又设黑龙江将军、屯田永戍、开通驿路、预储粮饷，一举扭转顺治朝进剿而不能守的困局，将黑龙江流域纳入直接军事管辖。两度用兵，一胜而毁城不取，再胜而围而不歼，皆以「以战逼和」为度，体现传统天下秩序下修德安边、怀柔远人的政治逻辑。《尼布楚条约》确认外兴安岭以南、额尔古纳河以东属清，为东北赢得约一个半世纪的安定；然战胜而让尼布楚、撤兵毁城，亦见清廷于近代国际格局尚乏深识，常备边防未立，为近代东北危机伏下远因。",
