    interpretation: "洋务运动的深层逻辑，在「中学为体，西学为用」：认定中国政教伦理本自完美，所缺唯坚船利炮、机器工艺。这一前提注定它止步于器物：工厂设矣而官场积弊随之，企业办矣而商权不彰；各省督抚各立门户、自筹经费，全国无统筹之局，工业零散而屡兴屡辍；海军经费移作修园之用，甲午之前北洋已数年未添舰炮，而日本正举国扩张。然洋务之功亦不可泯：中国第一批近代工厂、第一条电报线路、第一支近代海军、第一批出洋留学生皆由此而出，詹天佑、严复等俱受其泽。它开了风气、育了人才、奠了根基，使近代化进程一旦启动便不可逆转；其结局又昭然示人：仅恃器物之变，不足以致国家真正富强，制度与人心之变，终不可避。",
