      {
        heading: "十日屠城，八十万冤",
        paragraphs: [
          "城破之后，多铎以扬州军民抵抗日久、清军攻城伤亡颇重为由，下令纵兵屠城。自四月二十五日起，清兵在城内挨户搜掠，刀砍枪刺，纵火焚屋，屠戮持续十日，至五月五日方才「封刀」。百姓奔逃无门，投河自尽者填塞街巷，河水为之变色。亲历其事者王秀楚事后写成《扬州十日记》，逐日记述所见惨状：清兵沿途呼喝，逐户搜杀，藏于沟渠、柴堆之中者亦不能免。据书中所记，事后清查焚尸簿册，载明收殓焚化之数「前后约计八十万余」。",
          "此八十万之数是否即为遇害的确切人数，后世学者多有讨论：扬州府城常住居民或不及此数，册中所记应包括战前避难入城的外地人口；但无论数字如何折算，屠城规模之大、手段之惨酷，于清方档案、明人野史与西洋传教士记载中皆有印证，并无异辞。史可法遗骸终不可寻，其义子史德威觅得衣冠，葬于扬州城外广储门外梅花岭。扬州十日与稍后发生的嘉定三屠并称，成为清初江南最惨酷的两桩屠戮事件。五月十五日，多铎进入南京，弘光帝出奔被俘；然而屠戮换得的一时臣服，终在剃发令颁行之后被更大规模的江南抗清浪潮吞没。"
        ]
      }
