    interpretation: "扬州十日既是一城一地的悲剧，也是征服战争的逻辑结果。清军以数万之众南下，所最忌者并非南明军队的战力，而是江南的抵抗意志；屠城因此不只是一支军队的失控，而是带有威慑与报复双重目的的战争手段——攻城时清军伤亡颇重，多铎遂以屠戮立威，使沿途州县望风而降。就数字而言，《扬州十日记》所载八十万是否即为遇害确切人数，学界至今未有定论，但屠城事件本身于多方史料中皆有印证，不容否认。清代中叶以后，《扬州十日记》遭禁毁，乾隆帝虽追谥史可法「忠正」，却有意淡化这段记忆。清末此书自日本回流，成为排满革命宣传的依据，扬州十日由此从家族记忆进入民族记忆，影响至今。",
