          "道光二十二年五月，英军攻陷浙江乍浦。六月，英舰进犯长江口，江南提督陈化成坚守吴淞炮台，这位年近七旬的老将亲燃大炮，重创敌舰，终因孤军无援力战殉国，吴淞、上海相继陷落。七月，英军沿长江西进，直趋南京。一路之上，清军虽不乏浴血之士，然调度失当、装备悬殊，节节败退之势已不可挽回。"
