    interpretation: "义和团是近代中国底层民众在列强侵略与教会压迫下的一次自发性反抗，其御侮之心有其可矜之处；然以降神符咒为能事，以「灭洋」为号召，焚教堂、杀教民、毁铁路电线，又带有浓厚蒙昧色彩。慈禧集团始则纵容利用，欲以拳民对抗洋人、稳固政变之局；战败之后则翻脸无情，转而痛剿杀戮以媚洋人，其卖民求存之态，尽露封建朝廷之腐朽本质。《辛丑条约》赔款四亿五千万两，依当时中国人口约四亿五千万计，每人一两，本息合计九亿八千二百余万两，海关、常关、盐税尽被抵押。东南督抚擅行「东南互保」，清廷威权下移。此役之后，清廷内失民心，外丧权柄，十年之后，革命起而帝制终。",
