    summary: "颙琰，清仁宗，乾隆帝第十五子，原名永琰，即位后改「永」为「颙」以避御名。嘉庆元年（1796）正月受禅即位，太上皇训政三年，和珅专权如故。嘉庆四年亲政，即下和珅于狱，宣布二十大罪，赐死籍没，并罢贡献、黜奢崇俭，一时有更新之望。然同期白莲教起于川楚，蔓延五省，历时九年，耗银约二亿两；嘉庆十八年，天理教徒竟攻入紫禁城，隆宗门匾额箭痕至今犹存。在位二十五年，勤政图治而国势日替，清王朝由盛转衰之势，已非一人之力可挽。",
    background: "颙琰所承，是乾隆盛世繁华尽头的烂摊子。乾隆一朝，西师之役、南巡、万寿靡费无算；晚年倚任大学士和珅，任其擅权二十年，朝野贿赂公行，「议罪银」之设更使贪墨者输银自赎，吏治由是整体腐烂。地方上，人口自乾隆初年一亿余万，增至嘉庆初年的近三亿；耕地不增，流民遍野，川楚陕交界山区聚集数百万棚民，白莲教等秘密宗教乘势蔓延。武备方面，八旗、绿营承平数十年，将弁冒功吃饷，兵不习将，将不习兵。乾隆六十年（1795）九月，御极已满六十年的乾隆帝宣布立皇十五子嘉亲王永琰为皇太子，定明年正月初一行禅位之礼。次年正月朔，受禅大典于太和殿举行，三十七岁的颙琰即位，改元嘉庆，尊乾隆帝为太上皇帝。然此后三年，章奏先呈太上皇裁决，和珅仍以大学士、军机大臣、步军统领之尊弄权，时人阴称「二皇帝」——新君面对的，是千疮百孔的帝国。",
