          "嘉庆四年（1799）正月初三，太上皇帝崩于养心殿，颙琰始亲政。当月即下和珅于刑部狱，命王大臣会讯，宣谕二十大罪：欺罔擅权、结党营私、贪黩无艺，家中珍珠手串、宝石朝珠逾制无数。正月十八日，赐和珅于狱中自尽，籍没家产；其党羽福长安等分别治罪，和珅柄政二十年之局，于一月间倾覆。籍没家产折银之数，自数千万两至八亿两，记载不一，民间遂有「和珅跌倒，嘉庆吃饱」之谣。然颙琰处置颇为克制：和珅之罪止于其身，未兴大狱，朝局以稳为先。",
          "诛珅之外，颙琰更行刷新之政：颁诏求言，罢各省进献珍珠、玉器、古玩，禁织造、盐政贡献名物；宫中岁时庆赏一切从减，亲政之初即以崇俭为天下倡。又起用师傅朱珪入京为上书房总师傅，召直臣洪亮吉来京。洪亮吉上《平邪教疏》并痛陈时弊，颙琰初嘉纳之，终以其言辞激切，发遣伊犁，次年方赦还——求言之量，不过如此。然罢贡献、释冤狱、广言路之举，仍使朝野一时有更新之望。"
