          "嘉庆三年，王聪儿、姚之富部在湖北郧西三岔河陷入绝境，跳崖身亡；然四川徐天德、王登廷诸部犹往来川陕，出没无常。颙琰遂采坚壁清野之策，令川楚陕地方筑堡团练，清野以断教军粮援；又行招抚离间，赦免胁从。至嘉庆九年（1804）九月，最后一批教军首领苟文明等败死，起事始告平定。前后九年余，清廷军费约耗白银二亿两，几等于五年财政收入；国库为之一空，捐纳自此大开，卖官鬻爵渐成常制。",
