        text: "仁宗初逢训政，恭谨无违。迨躬莅万几，锄奸登善，削平逋寇，捕治海盗，力握要枢，崇俭勤事，辟地移民，治绩颇盛。然承贪污盈廷之弊，又值教匪、海盗、天理教之乱，吏治民风，日趋浇漓，而清之治亦渐替矣。",
