    interpretation: "载湉之悲剧，非一人之悲剧，乃皇权结构之悲剧。清制皇帝亲政后，太后训政之余威仍在。载湉以旁支入继，无母族势力，无藩邸旧臣，无一兵一卒之可恃。其变法之志，虽为救亡图存，然所用之人皆无实权，所行之事皆触大利。维新一派欲以一纸诏书更易二百年之官僚体制，其势不能成。论者或以载湉为有心无国之君，然观其一生，非无志也，实无权也；非不知也，实不能也。其崩于瀛台，距清亡仅三年，可视为一王朝末路之缩影。",
