    interpretation: "曾国藩一生，处数千年未有之变局的开端，而以一个传统理学家的身份应对了全部难题。他以书生典兵，不恃奇谋，唯以结硬寨、打呆仗的笨功夫与太平天国作长期消耗——这既是性格使然，也是对自身资源禀赋的清醒认知：湘军无朝廷经制之饷，无百战之将，唯恃人心与纪律。战后他主动裁撤湘军，深知功高震主之理，以自退保全了自身，却也为清廷留下督抚权重、兵为将有的难解之局——清末地方势力的坐大，实肇端于此。洋务上他办制造、派留学，开一代风气，并未触及制度根本。身后名声两极：誉之者称中兴第一名臣，毁之者以其镇压太平天国、办理天津教案为咎。家书以其躬行实践，成为修身齐家的文本；托名曾国藩的《冰鉴》流布于民间相术之间，亦可见其名望之深。李鸿章、左宗棠皆出其门下，承其衣钵，各成格局。",
