    interpretation: "中法战争之奇，不在战场，而在庙堂。以兵锋论，冯子材镇南关破敌、刘铭传挫法军于沪尾，皆可言胜；然清廷乘胜求和，弃越南、开口岸，故时人有「中国不败而败，法国不胜而胜」之叹。考其根由，慈禧太后以战局为权柄，甲申易枢、和战无常，庙堂之计皆服从内政；地方督抚各自为政，海军无统一指挥，马尾之覆败绝非偶然。和议之速成，一因国库空虚，二因法舰封锁，三因日本乘朝鲜甲申政变起衅，清廷急于抽身。其后果至为深巨：法国势力自越南深入云南、广西，铁路利权层层旁落；台湾因战守之功而建省，海军衙门亦因海防之痛而创设，洋务自强由此转入更急切的变法之议。亦有学者以为，清廷以宗藩虚名易边境实利，未尝无现实考量，然西南由此尽失屏障，实为十年后列强瓜分之祸开其端。",
