          "咸丰十年（1860）八月，英法联军攻陷通州，咸丰帝以「北狩」为名走避热河避暑山庄，留恭亲王奕䜣为钦差便宜行事全权大臣，与大学士桂良、户部左侍郎文祥留京议和。九月，奕䜣先与英国全权大臣额尔金签订《中英北京条约》，继与法国全权大臣葛罗签订《中法北京条约》，并互换《天津条约》批准书。英法军队暂驻京城，条约条款次第落实，留京王大臣从此身处对外交涉的第一线。",
          "战前清廷并无专管外交的常设机构。藩属朝贡之事归礼部与理藩院，俄罗斯事务由理藩院兼理；五口通商以来，对外交涉例由两广总督兼「五口通商大臣」经办，遇有重大争端则派钦差一事一办。公使驻京一条自咸丰八年（1858）《天津条约》谈判起即成争执焦点，咸丰帝甚至宁可全免洋货关税，也盼望各国公使「不入京」。联军入京的炮火证明，这一套以「羁縻」「抚夷」为底色的旧办法已经彻底失效。",
          "十一月，奕䜣与桂良、文祥联衔上奏《通筹夷务全局折》，列六条章程，首条即「京师请设立总理各国事务衙门，以专责成」。奏中特意将「各国事务」与「通商」并提，以办理通商为名、行统办外交之实，回避「夷署」「藩部」之名以免触犯朝议。咸丰十年十二月初十日（1861年1月20日），上谕准如所请，命奕䜣、桂良、文祥管理总理各国事务衙门。这是清朝开国二百余年来首次设立的常设中枢对外交涉机构。"
