          "同治十年（1871），曾国藩、李鸿章联名上奏，援容闳所拟章程，请选派幼童赴泰西学习军政、船政、制造诸学。同治十一年（1872）七月，首批留美幼童三十名自上海启行，此后三年间续派三批，合计一百二十名，全部由总理衙门经理其事，陈兰彬、容闳分任正副监督。这是中国历史上第一次由政府组织的留洋教育，詹天佑、唐绍仪等即在其中，后来多成近代路矿、外交骨干。",
          "光绪二年（1876），总理衙门奏定《出使章程》，各国公使常驻北京既成事实，中国亦须遣使驻外。光绪三年（1877）正月，郭嵩焘一行抵达伦敦，中国第一个驻外使馆在英国设立；此后驻美、驻日、驻德、驻法使馆相继成立，领事制度渐次铺开，海外保护与侨务自此有专司。总理衙门还主持架设电报线路、核准轮船招商局立案、议办开平煤矿与淞沪铁路诸事。在军机处之外，它实际构成综理洋务的中枢。"
