        heading: "舆榇西征，复我新疆",
        paragraphs: [
          "新疆危机酿于同治年间：同治四年（1865），中亚浩罕国军官阿古柏率军侵入南疆，建立「哲德沙尔汗国」；同治十年（1871），沙俄乘乱强占伊犁，扬言「代为收复」。同治十三年（1874）日本犯台湾后，朝野遂有海防、塞防孰重之辩：直隶总督李鸿章主海防，欲暂弃关外，专务东南；左宗棠则主「海塞并重」，奏称「重新疆者，所以保蒙古；保蒙古者，所以卫京师」，西北失则蒙古危、京师震动，东南亦不得安。光绪元年（1875）三月，清廷纳其议，授左宗棠钦差大臣、督办新疆军务，金顺为帮办，统筹西征。",
          "左宗棠受命后，先事筹粮、筹饷、筹转运：于上海、汉口借洋款，于归化、包头采粮，沿河西走廊设运粮台站，前后运粮数千万斤。光绪二年（1876）四月，湘军将领刘锦棠率部出关，八月克古牧地、乌鲁木齐，十一月下玛纳斯，北疆尽复。三年（1877）四月，西军三路并进，连克达坂、吐鲁番、托克逊，阿古柏穷蹙，于库尔勒身亡，其子伯克胡里西逃。刘锦棠乘胜南进，秋冬之际连克库尔勒、库车、阿克苏、乌什，光绪三年十一月（1878年1月）克和阗，南疆平定。除伊犁外，新疆全境收复，左宗棠以功晋封二等恪靖侯。",
          "伊犁仍为沙俄所据，崇厚出使俄国擅签条约，朝野哗然，约遂废。光绪六年（1880），左宗棠以六十九岁高龄舁榇出关，抬棺进驻哈密，示以武力收回伊犁之决心，并分兵三路向伊犁推进。光绪七年（1881）正月，曾纪泽与俄国改订《中俄伊犁条约》，伊犁终得归还。左宗棠早在光绪三年即上疏请新疆建省，谓「设行省，改郡县，为新疆久安之策」。光绪十年（1884）十月，清廷颁诏新疆建省，以刘锦棠为甘肃新疆巡抚，新疆自此与内地行省同制，西北边防为之一固。"
        ]
