      {
        heading: "船政图强，遗泽东南",
        paragraphs: [
          "左宗棠不仅是疆臣，亦是洋务自强的先驱。同治五年（1866）任闽浙总督时，奏设福州船政局于马尾，聘法国人日意格、德克碑为正副监督，创设船厂与「求是堂艺局」（船政学堂），招生学习造船、驾驶、轮机、测绘诸学，又派学生出洋留学。船政局先后造成兵轮、商轮数十艘，船政学堂培育出严复、邓世昌、刘步蟾等海军将领，为中国近代海军与造船工业的发端之地。他调任陕甘后，荐沈葆桢接办船政，成一时之盛。",
          "在西北，左宗棠同样以自强为务：设西安、兰州制造局，仿造洋枪洋炮以供西征军需；办甘肃织呢局，购德国机器，倡导畜牧纺织；凿井开渠、整修自潼关至新疆驿道，令军士沿途植柳，后人称「左公柳」。他又禁罂粟、劝农桑，刊发《棉花图》《种棉十要》，教陇民纺织，欲以实业固边。这些举措成效虽参差，却是近代西北工业化的最早尝试。",
          "光绪十年（1884）中法战争起，左宗棠奉召入京，授军机大臣，旋外放督办闽海军务。他力主抗击法军，于福州布防、援应台湾，遣王诗正率军渡台助守。光绪十一年七月二十七日（1885年9月5日），左宗棠积劳病逝于福州，年七十四。遗折犹言「越事和战，实中国强弱一大关键」，拳拳忧国，至死不释。朝廷赠太傅，谥文襄，葬于长沙。其一生以书生典兵，东定东南，西复新疆，内办洋务，外御强邻，为同治、光绪间罕有其匹之重臣。"
        ]
      }
