    interpretation: "左宗棠一生，正处清王朝内外交困之交。其事功之要，在于以天下大局度势：海防、塞防之争表面是军费分配之争，实为地缘战略之争——左宗棠洞察新疆、蒙古、京师唇齿相依的结构，认定西北一失则全局皆危，故能力排众议，收复一百六十余万平方公里疆土，此为近代中国抵御外侮最辉煌之一役。其洋务实践亦不徒在船坚炮利，而重人才、重实业、重久安之策，船政学堂与新疆建省皆垂之久远。史称其「刚明耐苦，洞究边事」，信非虚誉。左宗棠病逝之年距甲午之战不满十年，其经营之海防、塞防后来屡经挫折，而新疆至今为中国行省，其功不可没。",
